import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import Swal from "sweetalert2";

const DETECCIONES = [
  { id: 1, fecha: "24/07/2025", hora: "09:15 a.m.", lote: "Lote 7", bloque: "Bloque E", resultado: "Sigatoka Negra", severidad: "Moderado", image: "https://images.unsplash.com/photo-1524593166156-312f362cada0?q=80&w=100" },
  { id: 2, fecha: "24/07/2025", hora: "08:45 a.m.", lote: "Lote 6", bloque: "Bloque A", resultado: "Sigatoka Negra", severidad: "Severo",   image: "https://images.unsplash.com/photo-1501004318641-b39e6451bec6?q=80&w=100" },
  { id: 3, fecha: "24/07/2025", hora: "04:30 p.m.", lote: "Lote 5", bloque: "Bloque D", resultado: "Sigatoka Negra", severidad: "Leve",     image: "https://images.unsplash.com/photo-1471193945509-9ad0617afabf?q=80&w=100" },
  { id: 4, fecha: "23/07/2025", hora: "11:20 a.m.", lote: "Lote 4", bloque: "Bloque B", resultado: "Sigatoka Negra", severidad: "Moderado", image: "https://images.unsplash.com/photo-1466692476868-aef1dfb1e735?q=80&w=100" },
  { id: 5, fecha: "22/07/2025", hora: "03:19 p.m.", lote: "Lote 3", bloque: "Bloque C", resultado: "Sigatoka Negra", severidad: "Leve",     image: "https://images.unsplash.com/photo-1524593166156-312f362cada0?q=80&w=100" },
];

const LOTES = [
  { nombre: "Lote 7 - Bloque B", cantidad: 28 },
  { nombre: "Lote 6 - Bloque A", cantidad: 24 },
  { nombre: "Lote 5 - Bloque D", cantidad: 20 },
  { nombre: "Lote 4 - Bloque B", cantidad: 18 },
  { nombre: "Lote 3 - Bloque C", cantidad: 16 },
];

const EVOLUCION = [
  { dia: "18 Jul", val: 22 },
  { dia: "19 Jul", val: 38 },
  { dia: "20 Jul", val: 45 },
  { dia: "21 Jul", val: 30 },
  { dia: "22 Jul", val: 52 },
  { dia: "23 Jul", val: 48 },
  { dia: "24 Jul", val: 68 },
];

const severidadConfig = {
  Moderado: { bg: "bg-orange-100", text: "text-orange-600", border: "border-orange-200" },
  Severo:   { bg: "bg-red-100",    text: "text-red-600",    border: "border-red-200"    },
  Leve:     { bg: "bg-green-100",  text: "text-green-700",  border: "border-green-200"  },
};

export default function HomePage() {
  const navigate = useNavigate();
  const { user, handleLogout } = useAuth();
  const [activePage, setActivePage] = useState("dashboard");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const canvasRef = useRef(null);

  const fullName = user?.displayName || user?.email?.split("@")[0] || "Usuario";
  const initials = fullName.split(" ").map(n => n[0]).join("").toUpperCase().slice(0, 2);
  const storageKey = `scans_${user?.uid || user?.email || "guest"}`;
  const detections = JSON.parse(localStorage.getItem(storageKey) || "[]");

  useEffect(() => {
    if (activePage === "dashboard") {
      setTimeout(dibujarGrafica, 100);
    }
  }, [activePage]);

  const dibujarGrafica = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const W = canvas.width, H = canvas.height;
    const pad = { top: 16, right: 16, bottom: 28, left: 36 };
    const vals = EVOLUCION.map(e => e.val);
    const maxVal = Math.max(...vals);

    ctx.clearRect(0, 0, W, H);

    for (let i = 0; i <= 4; i++) {
      const y = pad.top + ((H - pad.top - pad.bottom) / 4) * i;
      ctx.strokeStyle = "#e5e7eb";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(pad.left, y);
      ctx.lineTo(W - pad.right, y);
      ctx.stroke();
      ctx.fillStyle = "#9ca3af";
      ctx.font = "10px sans-serif";
      ctx.textAlign = "right";
      ctx.fillText(Math.round(maxVal - (maxVal / 4) * i), pad.left - 4, y + 4);
    }

    const pts = EVOLUCION.map((e, i) => ({
      x: pad.left + (i / (EVOLUCION.length - 1)) * (W - pad.left - pad.right),
      y: pad.top + (1 - e.val / maxVal) * (H - pad.top - pad.bottom),
    }));

    const grad = ctx.createLinearGradient(0, pad.top, 0, H - pad.bottom);
    grad.addColorStop(0, "rgba(34,107,34,0.15)");
    grad.addColorStop(1, "rgba(34,107,34,0)");
    ctx.beginPath();
    ctx.moveTo(pts[0].x, H - pad.bottom);
    pts.forEach(p => ctx.lineTo(p.x, p.y));
    ctx.lineTo(pts[pts.length - 1].x, H - pad.bottom);
    ctx.closePath();
    ctx.fillStyle = grad;
    ctx.fill();

    ctx.beginPath();
    ctx.strokeStyle = "#1f5e1f";
    ctx.lineWidth = 2.5;
    ctx.lineJoin = "round";
    pts.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
    ctx.stroke();

    pts.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
      ctx.fillStyle = "#1f5e1f";
      ctx.fill();
      ctx.strokeStyle = "white";
      ctx.lineWidth = 2;
      ctx.stroke();
    });

    EVOLUCION.forEach((e, i) => {
      const x = pad.left + (i / (EVOLUCION.length - 1)) * (W - pad.left - pad.right);
      ctx.fillStyle = "#6b7280";
      ctx.font = "10px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(e.dia, x, H - 4);
    });
  };

  const confirmLogout = () => {
    Swal.fire({
      title: "¿Cerrar sesión?",
      text: "Tendrás que iniciar sesión de nuevo.",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#1f5e1f",
      cancelButtonColor: "#9ca3af",
      confirmButtonText: "Sí, cerrar sesión",
      cancelButtonText: "Cancelar",
      background: "#f5f2ec",
      customClass: { popup: "rounded-3xl" },
    }).then(r => {
      if (r.isConfirmed) { handleLogout(); navigate("/login"); }
    });
  };

  const navItems = [
    { key: "dashboard",   label: "Dashboard",                   icon: "🏠", section: null },
    { key: "usuarios",    label: "Usuarios",                    icon: "👥", section: null },
    { key: "deteccion",   label: "Detección de Enfermedades",   icon: "🔬", section: "MÓDULOS" },
    { key: "seguimiento", label: "Recomendación y Seguimiento", icon: "🌿", section: null },
    { key: "geolocal",    label: "Geolocalización y Registro",  icon: "📍", section: null },
    { key: "informes",    label: "Visualización e Informes",    icon: "📊", section: null },
  ];

  const handleNav = (key) => {
    setActivePage(key);
    setSidebarOpen(false);
    if (key === "deteccion") navigate("/scan");
    if (key === "geolocal")  navigate("/map");
    if (key === "seguimiento") navigate("/result");
  };

  const pageTitle = {
    dashboard:   { title: "Panel de Control - Dashboard",      sub: "Resumen general de las operaciones de Sigatoka Negra" },
    deteccion:   { title: "Detección de Enfermedades",         sub: "Monitorea y gestiona las detecciones realizadas en campo" },
    seguimiento: { title: "Recomendación y Seguimiento",       sub: "Gestiona las recomendaciones de tratamiento" },
    geolocal:    { title: "Geolocalización y Registro",        sub: "Visualiza las zonas afectadas en el mapa" },
    informes:    { title: "Visualización e Informes",          sub: "Genera reportes y estadísticas del sistema" },
    usuarios:    { title: "Gestión de Usuarios",               sub: "Administra los usuarios del sistema" },
