        <div className="flex items-center gap-3">
          <button onClick={() => setSidebarOpen(true)} className="lg:hidden w-9 h-9 rounded-lg flex items-center justify-center hover:bg-gray-100">
            ☰
          </button>
          <div>
            <h1 className="font-bold text-base sm:text-lg text-gray-900 leading-tight">{current.title}</h1>
            <p className="text-xs text-gray-400 hidden sm:block">{current.sub}</p>
