              <div className="w-9 h-9 rounded-full bg-green-700 flex items-center justify-center text-white text-sm font-bold">{initials}</div>
            )}
            <div className="hidden sm:block">
              <p className="text-sm font-semibold text-gray-800 leading-tight">{fullName}</p>
              <p className="text-xs text-gray-400">Técnico de Campo</p>
            </div>
            <span className="text-gray-400 text-xs hidden sm:block">▾</span>
          </div>
        </div>
      </header>

      <div className="flex flex-1">

        {sidebarOpen && <div className="fixed inset-0 bg-black/40 z-30 lg:hidden" onClick={() => setSidebarOpen(false)} />}

        {/* SIDEBAR */}
        <aside className={`fixed lg:sticky top-0 left-0 h-screen lg:h-[calc(100vh-57px)] w-56 bg-[#1a3a1a] flex flex-col z-40 transition-transform duration-300
          ${sidebarOpen ? "translate-x-0" : "-translate-x-full"} lg:translate-x-0`}
        >
          {/* Logo */}
          <div className="flex items-center gap-2.5 px-4 py-4 border-b border-white/10">
            <div className="w-9 h-9 rounded-xl bg-green-600 flex items-center justify-center shrink-0">
              <svg width="20" height="20" viewBox="0 0 80 80" fill="none">
                <ellipse cx="30" cy="40" rx="13" ry="20" fill="white" opacity="0.9" transform="rotate(-15 30 40)" />
                <ellipse cx="50" cy="38" rx="13" ry="20" fill="white" opacity="0.75" transform="rotate(15 50 38)" />
                <line x1="40" y1="60" x2="40" y2="72" stroke="white" strokeWidth="3" strokeLinecap="round" />
              </svg>
            </div>
            <div className="min-w-0">
              <p className="text-white font-bold text-sm leading-tight truncate">Sigatoka Negra</p>
              <p className="text-green-300 text-xs truncate">Hacienda San Luis</p>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden ml-auto text-white/50 hover:text-white shrink-0">✕</button>
          </div>

          {/* Usuario sidebar */}
          <div className="flex items-center gap-2.5 px-4 py-3 border-b border-white/10">
            {user?.photoURL ? (
              <img src={user.photoURL} referrerPolicy="no-referrer" alt="" className="w-8 h-8 rounded-full object-cover shrink-0" />
            ) : (
              <div className="w-8 h-8 rounded-full bg-green-500 flex items-center justify-center text-white text-xs font-bold shrink-0">{initials}</div>
