          </div>
        </aside>

        {/* CONTENIDO */}
        <main className="flex-1 p-4 sm:p-5 space-y-4 overflow-auto min-w-0">

          {/* STATS */}
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
            {[
              { icon: "📋", bg: "bg-green-50",  iconBg: "bg-green-100",  val: detections.length || 128, label: "Detecciones Totales",     sub: "+15 esta semana",        subColor: "text-green-600"  },
              { icon: "🍃", bg: "bg-red-50",    iconBg: "bg-red-100",    val: 68,                       label: "Sigatoka Negra",          sub: "53.1% del total",        subColor: "text-red-500"    },
              { icon: "🛡️", bg: "bg-orange-50", iconBg: "bg-orange-100", val: 42,                       label: "Nivel Moderado - Severo", sub: "32.8% del total",        subColor: "text-orange-500" },
              { icon: "📅", bg: "bg-blue-50",   iconBg: "bg-blue-100",   val: 24,                       label: "Detecciones esta semana", sub: "+6 respecto a la semana pasada", subColor: "text-blue-500" },
            ].map((s, i) => (
