                          </td>
                          <td className="px-3 py-2.5">
                            <p className="font-medium text-gray-800">{d.lote}</p>
                            <p className="text-gray-400 text-[11px]">{d.bloque}</p>
                          </td>
                          <td className="px-3 py-2.5 font-semibold text-red-500">{d.resultado}</td>
                          <td className="px-3 py-2.5">
                            <span className={`font-semibold px-2.5 py-1 rounded-full border ${sev.bg} ${sev.text} ${sev.border}`}>
                              {d.severidad}
                            </span>
                          </td>
                          <td className="px-3 py-2.5 text-center text-green-600 text-base">👁️</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>

            <div className="bg-white rounded-2xl border border-gray-100 p-5">
              <h2 className="font-bold text-gray-800 text-sm mb-4">Detecciones por Nivel de Sigatoka Negra</h2>
              <div className="flex flex-col items-center">
                <DonutChart />
                <div className="space-y-2 w-full mt-4">
